CAT = "sgsecTerror"; SEG = "TER"
# Terrorist threats: PLRD refresher training package (summary of SEC-OBS-1002-1.1 Threat
# Observation, Recognise Terrorist Threats, and its bomb threat and suspicious parcel scenarios),
# SGSecure (sgsecure.gov.sg, Run Hide Tell) and SCDF Civil Defence Emergency Handbook (10th ed.,
# 2026: bomb threats, explosions, SGSecure A.I.S.U.).
Q = [
("Which description fits terrorism in the Recognise Terrorist Threats material?",
 "Violence to spread fear for a political aim", ["Any crime committed with a weapon", "Damage to property for money", "Fighting between rival street gangs"],
 "The PLRD summary describes terrorism as violence or the threat of violence, used as a means to an end, to create fear and instability for a political aim."),
("An attacker acts alone, outside any command structure and without help from a group. This is called:",
 "A lone wolf attack", ["A group attack", "A proxy attack", "A sleeper cell attack"],
 "A lone wolf attack is carried out by someone acting alone without any group's assistance. A group attack is a coordinated assault by several attackers."),
("Which is a current trend in terrorism named in the PLRD material?",
 "Self-radicalisation", ["Fewer attacks yearly", "Military targets only", "Groups cutting ties"],
 "PLRD lists growing links between terrorist groups, emerging threats such as far-right extremism, self-radicalisation and more frequent attacks."),
("Which method is listed as a common terrorist modus operandi?",
 "A vehicle used as a weapon", ["Forging shop receipts", "Hacking parking meters", "Selling counterfeit goods"],
 "PLRD's common methods include knife or axe attacks, vehicles used as weapons, active shooters and suicide bombers."),
("In the four stages of a terrorist attack, what comes right after setting the objectives?",
 "Choosing the target", ["Carrying out the attack", "Escaping the country", "Recruiting new members"],
 "The four stages are: objectives, target selection, planning the attack, then carrying it out."),
("A shopping mall where crowds gather is what kind of target?",
 "A soft target", ["A hard target", "A symbolic target", "A remote target"],
 "Soft targets are civilian sites where people gather in large numbers. Hard targets are government buildings, key installations and airports."),
("A national landmark chosen for its meaning would be classed as:",
 "A symbolic target", ["A soft target", "A mobile target", "A secondary target"],
 "Symbolic targets are landmarks and places of significance, chosen for what they represent."),
("An attack aimed at a visiting VIP is classed as:",
 "Person-centric", ["Economic", "Hard", "Random"],
 "Person-centric targets are individuals such as VIPs and politicians."),
("During which stage would attackers watch the target and pick the date, time and place?",
 "Planning the attack", ["Setting objectives", "Choosing the target", "Carrying out the attack"],
 "PLRD gives observing the target and selecting the date, time and place as part of stage 3, planning the attack."),
("Which action is a sign of casing or hostile surveillance of a facility?",
 "Testing guards' alertness", ["Delivering a parcel on time", "Asking for a visitor's pass", "Using the main passenger lift"],
 "PLRD lists studying access points and the facade, filming the facility, prolonged loitering, seeking sensitive information about events and testing the alertness of security personnel."),
("Someone asks an officer detailed questions about security at an upcoming event. This may be:",
 "Information gathering", ["A normal guest query", "A job application", "Proof of an attack"],
 "Attempting to obtain sensitive information on an upcoming event is a listed casing activity. It is a reason to note details and report, not proof of an attack."),
("Which is a tell-tale sign of a person-borne improvised explosive device (IED)?",
 "Wires under clothing", ["A large umbrella", "Reading glasses", "A walking stick"],
 "Signs include oversized clothes hiding items, electrical wires sticking out from under clothing or bags, hiding identity with a helmet, long loitering and leaving a parcel in a crowded place."),
("A visitor will not explain why he is there and becomes uncooperative. In threat observation, this is:",
 "A possible IED warning sign", ["Normal for a lost tourist", "A reason to ignore him", "Proof that he is armed"],
 "Being unable to give a reasonable explanation or being uncooperative about the purpose of the visit is one of the listed person-borne IED signs."),
("Which is a sign of a possible vehicle-borne IED?",
 "Sunken tyres from a heavy load", ["A freshly washed exterior", "Dark tinted window film", "A taxi waiting at the stand"],
 "PLRD lists flammable or suspicious cargo, a heavy load that sinks the tyres and suspension, objects under the vehicle and signs of tampering."),
("A shiny new number plate is fitted to an old, dirty car. This may indicate:",
 "Tampering", ["A careful owner", "A rental car", "A recent car wash"],
 "A new licence plate on an old, dirty car is PLRD's example of signs that a vehicle has been tampered with, a vehicle-borne IED indicator."),
("A van at the gate carries an LPG cylinder with no reason for it. Under threat observation this is:",
 "A suspicious load", ["A catering delivery", "A breakdown sign", "A cleaning supply"],
 "Vehicles carrying flammable items such as LPG cylinders or suspicious items are listed as possible vehicle-borne IED signs, so the officer checks and reports."),
("Which is a sign of a letter or parcel bomb?",
 "Oily stains on the wrapping", ["A printed return address", "A courier barcode label", "A neat, flat envelope"],
 "Signs include excessive securing material, oily stains or discolouration, an almond-like smell, a ticking sound, wires or foil sticking out and excessive postage."),
("A parcel smells of almonds and is wrapped in layers of tape. What should the officer do?",
 "Leave it unopened", ["Open it carefully", "Shake it to listen", "Post it back"],
 "Excessive tape and an almond smell are listed signs. SCDF warns most such bombs are made to go off when the wrapping is torn or cut, so it is never opened."),
("Which mail marking can add suspicion to a parcel with other warning signs?",
 "\"Confidential\"", ["\"Fragile, handle with care\"", "\"This way up\"", "\"Keep dry\""],
 "SCDF lists restrictive markings such as \"Personal\", \"Confidential\" and \"To be opened by addressee only\", along with excessive postage and unfamiliar handwriting."),
("A drone hovers over the same restricted area for a long time with no operator in sight. This suggests:",
 "UAV surveillance", ["A hobby flight", "A weather survey", "A drone delivery"],
 "PLRD lists UAVs flying at security-sensitive locations, hovering at the same spot for a time, and no sign of the operator nearby as signs of casing by UAV."),
("A suspicious parcel is found during a search. What should the officer do with their walkie-talkie?",
 "Switch it off", ["Use it to call for help", "Set it beside the parcel", "Turn the volume up"],
 "The PLRD scenario says to switch off communication devices such as walkie-talkies near a suspicious parcel and to use a fixed line to inform the Control Room."),
("How large an area should be cordoned off around a suspected bomb?",
 "At least 100 m radius", ["About 10 m radius", "Just the room it is in", "At least 1 km radius"],
 "The PLRD scenario says to cordon an area of at least 100 metres radius with a \"Danger Keep Out\" sign facing out."),
("A suspected bomb is found indoors. What should be done with the windows and doors?",
 "Open them", ["Close and lock them", "Tape them over", "Leave them alone"],
 "PLRD and SCDF advise opening windows and doors when a bomb is indoors to minimise the impact of an explosion and of shattering glass."),
("A caller says a bomb has been placed in the building. What should the officer do while on the line?",
 "Keep the caller talking", ["Hang up and run outside", "Argue to test the caller", "Say the police are coming"],
 "SCDF advises keeping the caller talking as long as possible, writing down the exact words, and asking when, where, what type and why, without antagonising the caller."),
("During a bomb threat call, what should the officer signal a partner to do?",
 "Ask police to trace it", ["Sound the fire alarm", "Unplug the telephone", "Leave the building"],
 "The PLRD scenario says to signal a partner to call the Police for trace call action, while following the Bomb Threat Call Checklist."),
("During a bomb threat call, what must the officer avoid?",
 "Taunting the caller", ["Writing down the words", "Asking where the bomb is", "Noting the caller's accent"],
 "SCDF says not to antagonise or taunt the caller. The officer keeps them talking, records the exact words, asks when, where and why, and notes the voice, accent and background noise."),
("Why should officers not use mobile phones near a suspected bomb or explosion site?",
 "They may set off a device", ["They drain the battery fast", "They are banned in lobbies", "They upset the injured"],
 "SCDF warns that mobile phones, radios and electronic equipment at a bomb site may trigger secondary explosions."),
("In an armed attack, what does the RUN step of Run, Hide, Tell advise?",
 "Leave quietly by a safe route", ["Negotiate with the attackers", "Collect your belongings first", "Head towards the noise"],
 "SGSecure advises moving quickly and quietly away using the safest route, not surrendering or negotiating, and leaving belongings behind."),
("When hiding from attackers, what should be done with a mobile phone?",
 "Set it to silent", ["Turn the ringer up", "Play calming music", "Call friends loudly"],
 "SGSecure's HIDE step says to stay out of sight, be quiet, switch the phone to silent mode, lock yourself in and stay away from doors."),
("If it is not safe to speak, how can the police be alerted during an attack?",
 "SMS to 70999", ["SMS to 995", "A call to 1777", "An email to HQ"],
 "SGSecure's TELL step: call 999, or SMS 70999 if it is not safe to talk, or use the SGSecure app to send details about the attackers and their location."),
("SGSecure's A.I.S.U. reminder asks people to look out for anything:",
 "Abnormal, Irregular, Strange or Unusual", ["Armed, Illegal, Secret or Urgent", "Alarming, Isolated, Small or Unknown", "Angry, Idle, Silent or Upset"],
 "SGSecure's vigilance message is to keep a lookout for anything Abnormal, Irregular, Strange or Unusual, such as unattended articles or suspicious behaviour."),
("After a terror attack, what should people do with unverified videos they receive?",
 "Not share them", ["Forward them widely", "Post them online", "Edit, then share"],
 "SGSecure advises not posting or sharing unverified videos or photos, to avoid panic and disharmony, and getting updates from official sources."),
]
